455	/// Assembles the full MatrixReport for `packages`. Map keys are each
456	/// package's ecosystem-qualified id (`PackageId::display_name()` -- a bare
457	/// name when the package was never promoted, `ecosystem/name` once a
458	/// same-name package in another ecosystem forced promotion; the
459	/// BTreeMap ordering comes from this for free) so a Cargo package and an npm
460	/// package sharing a bare name (the common napi split layout) never collide
461	/// on the same map entry; a package contributes no platformTargets entry when it declares neither
462	/// napi.targets nor [tool.maturin].targets, and no runtimeVersions entry when
463	/// it declares neither engines.node nor requires-python.
464	///
465	/// Each package's `package.json`/`pyproject.toml` is read and parsed at most
466	/// once here and the resulting value shared between the platform-target and
467	/// runtime-version extraction paths, instead of each independently
468	/// re-reading and re-parsing the same file from disk.
469	pub(crate) fn build_matrix_report(
470	    packages: &[MatrixPackageInput],
471	    napi_crates: Option<&[NapiCrate]>,
472	) -> Result<MatrixReport, GraphError> {
473	    let mut platform_targets = BTreeMap::new();
474	    let mut runtime_versions = BTreeMap::new();
475	    let mut diagnostics = Vec::new();
476	
477	    for pkg in packages {
478	        let pkg_json_val = parse_package_json(&pkg.dir_abs.join("package.json"))?;
479	        let pyproject_val = parse_pyproject_toml(&pkg.dir_abs.join("pyproject.toml"))?;
480	
481	        let (group, diags) = assemble_platform_target_group(
482	            &pkg.dir_abs,
483	            &pkg.dir_rel,
484	            &pkg.name,
485	            &pkg.id,
486	            pkg_json_val.as_ref(),
487	            pyproject_val.as_ref(),
488	        )?;
489	        if let Some(mut group) = group {
490	            if let (PlatformTargetKind::Napi, Some(pkg_json), Some(napi_crates), false) =
491	                (group.kind, pkg_json_val.as_ref(), napi_crates, group.targets.is_empty())
492	            {
493	                let manifest_path = napi_manifest_path(pkg, pkg_json, napi_crates)?;
494	                for target in &mut group.targets {
495	                    target.manifest_path = manifest_path.clone();
496	                }
497	            }
498	            platform_targets.insert(pkg.id.display_name(), group);
499	        }
500	        diagnostics.extend(diags);
501	
502	        let rv = assemble_runtime_versions(&pkg.dir_abs, pkg_json_val.as_ref(), pyproject_val.as_ref())?;
503	        if !rv.is_empty() {
504	            runtime_versions.insert(pkg.id.display_name(), rv);
505	        }
506	    }
507	
508	    Ok(MatrixReport {
509	        schema_version: callisto_model::PACKAGE_REPORT_SCHEMA_VERSION,
510	        platform_targets,
511	        runtime_versions,
512	        diagnostics,
513	    })
514	}
