526	/// Adds one `cargo` group per package from its `[[release.artifact]]` entries;
527	/// each target's `artifactName` is the slot's configured asset name.
528	pub(crate) fn add_release_artifact_groups(
529	    report: &mut MatrixReport,
530	    artifacts: &[ReleaseArtifactInput],
531	) -> Result<(), GraphError> {
532	    const SOURCE: &str = "[[release.artifact]]";
533	    for artifact in artifacts {
534	        let group = report
535	            .platform_targets
536	            .entry(artifact.id.display_name())
537	            .or_insert_with(|| PlatformTargetGroup {
538	                kind: PlatformTargetKind::Cargo,
539	                source: SOURCE.to_owned(),
540	                targets: Vec::new(),
541	            });
542	        if group.kind != PlatformTargetKind::Cargo {
543	            return Err(GraphError::PlatformTargetsWithReleaseArtifacts {
544	                package: artifact.id.clone(),
545	                source_field: group.source.clone(),
546	            });
547	        }
548	        match build_platform_target(&artifact.target, &artifact.dir_rel, &artifact.name) {
549	            Some(mut target) => {
550	                target.artifact_name = artifact.asset_name.clone();
551	                group.targets.push(target);
552	            }
553	            None => report.diagnostics.push(Diagnostic {
554	                code: DiagnosticCode::UnrecognisedPlatformTriple,
555	                severity: DiagnosticSeverity::Warning,
556	                message: format!(
557	                    "package `{}` declares unrecognised platform triple `{}` in `{SOURCE}`",
558	                    artifact.name, artifact.target
559	                ),
560	                package: Some(artifact.id.clone()),
561	                path: None,
562	                escalated_by: None,
563	                governed_by: None,
564	            }),
565	        }
566	        group.targets.sort_by(|a, b| {
567	            a.triple
568	                .cmp(&b.triple)
569	                .then_with(|| a.artifact_name.cmp(&b.artifact_name))
570	        });
571	    }
572	    report
573	        .platform_targets
574	        .retain(|_, group| !group.targets.is_empty() || group.kind != PlatformTargetKind::Cargo);
575	    Ok(())
576	}
