108	/// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
109	/// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
110	/// a bare name is accepted only when it names exactly one package.
111	fn resolve_selected_package(
112	    all_packages: &[&callisto_model::Package],
113	    identity: &crate::IdentityIndex,
114	    raw: &str,
115	) -> Result<PackageId, GraphError> {
116	    ConfigError::require_qualified(raw, "--package")?;
117	    let resolved = identity.resolve(raw)?;
118	    if all_packages.iter().any(|p| p.id == resolved) {
119	        Ok(resolved)
120	    } else {
121	        Err(GraphError::UnknownPackage { id: resolved })
122	    }
123	}
