106	/// Extracts `napi.targets` from an already-parsed `package.json` value (see
107	/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
108	/// is `Absent` (no platformTargets entry). A present `napi.targets`
109	/// that is not a JSON array of strings is a hard error -- strict
110	/// policy, propagating `callisto_manifests::read_napi_targets`'s error
111	/// as-is; unlike `NapiTargetsIndex::load`, which `.ok()`s the same shared
112	/// reader to silently drop non-array values instead.
113	pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
114	    match callisto_manifests::read_napi_targets(pkg_json_path, val).map_err(GraphError::Manifest)? {
115	        Some(triples) => Ok(NapiTargetsField::Present(triples)),
116	        None => Ok(NapiTargetsField::Absent),
