153	/// re-read and re-parse the file from disk.
154	pub(crate) fn parse_pyproject_toml(pyproject_path: &Path) -> Result<Option<toml::Value>, GraphError> {
155	    let Some(content) = callisto_model::strict_fs::read_optional(pyproject_path).map_err(|e| {
156	        GraphError::Manifest(ManifestError::Read {
157	            path: pyproject_path.to_path_buf(),
158	            message: e.to_string(),
159	        })
160	    })?
161	    else {
162	        return Ok(None);
163	    };
164	    let val = toml::from_str::<toml::Value>(&content).map_err(|e: toml::de::Error| {
165	        GraphError::Manifest(ManifestError::Parse {
166	            path: pyproject_path.to_path_buf(),
167	            format: ManifestFormat::PyprojectToml,
168	            message: e.to_string(),
169	        })
