161	    )
162	    .unwrap();
163	
164	    let maturin_dir = root.join("maturin-mod");
165	    std::fs::create_dir_all(&maturin_dir).unwrap();
166	    std::fs::write(
167	        maturin_dir.join("pyproject.toml"),
168	        "[project]\nname = \"maturin-mod\"\nversion = \"0.1.0\"\n\n[tool.maturin]\ntargets = [\"aarch64-apple-darwin\", \"x86_64-unknown-linux-gnu\"]\n",
169	    )
170	    .unwrap();
171	
172	    napi_crate(root, "napi-mod");
173	    let bin = env!("CARGO_BIN_EXE_callisto");
174	    let output = Command::new(bin)
175	        .args(["--cwd", &root.to_string_lossy(), "--format", "json", "matrix"])
