184	
185	    let json: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
186	    let napi_group = &json["platformTargets"]["cargo/napi-mod"];
187	    let maturin_group = &json["platformTargets"]["pypi/maturin-mod"];
